insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gratin de legume', 'Gratin de légumes', array['legume gratine']::text[], 'dish', $r$[{"title":"Gratin de légumes","intro":"Courgettes, poivrons et pommes de terre en béchamel légère, gratinés au fromage.","minutes":60,"calories":320,"difficulty":"Facile","imageSearch":"vegetable gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"lait","plural":"laits","qty":40,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":30,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":100,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Coupe les légumes en rondelles et fais cuire les pommes de terre 10 min à l'eau.","timer":{"label":"Cuisson","min":10}},{"text":"Fais une béchamel avec le beurre, la farine et le lait.","timer":null},{"text":"Range les légumes dans un plat, nappe de béchamel et couvre d'emmental.","timer":null},{"text":"Enfourne 35 min.","timer":{"label":"Four","min":35}}],"kids":true,"variant":"La classique","change":""},{"title":"Gratin de poireaux","intro":"Un gratin doux et crémeux, tout en poireaux.","minutes":50,"calories":300,"difficulty":"Facile","imageSearch":"leek gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poireau","plural":"poireaux","qty":5,"unit":"","have":false},{"name":"lait","plural":"laits","qty":40,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":30,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":100,"unit":"g","have":false},{"name":"muscade","plural":"muscade","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Coupe les poireaux en tronçons et fais-les fondre 10 min à la poêle avec un peu de beurre.","timer":{"label":"Poêle","min":10}},{"text":"Fais une béchamel avec le reste du beurre, la farine et le lait, puis ajoute la muscade.","timer":null},{"text":"Mets les poireaux dans un plat, nappe de béchamel et couvre d'emmental.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true,"variant":"Poireaux","change":"Avec des poireaux fondus en béchamel."},{"title":"Gratin de légumes d'hiver","intro":"Un gratin réconfortant aux légumes d'hiver.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"winter vegetable gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potiron","plural":"potiron","qty":600,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"poireau","plural":"poireaux","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":100,"unit":"g","have":false},{"name":"muscade","plural":"muscade","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Coupe le potiron en dés, les carottes en rondelles et les poireaux en tronçons.","timer":null},{"text":"Fais-les cuire 10 min à la vapeur.","timer":{"label":"Cuisson","min":10}},{"text":"Range-les dans un plat avec la crème, la muscade, le sel et le poivre, puis l'emmental.","timer":null},{"text":"Enfourne 30 min.","timer":{"label":"Four","min":30}}],"kids":true,"variant":"D'hiver","change":"Avec potiron, carottes et poireaux."}]$r$::jsonb, 'claude')
