cons, les œufs, le lait et le cacao.","timer":null},{"text":"Mélange bien.","timer":null},{"text":"Enfonce un carré de chocolat au centre de chaque bol.","timer":null},{"text":"Fais cuire chaque bol 2 min au micro-ondes.","timer":{"label":"Micro-ondes","min":2}}],"kids":true,"dessert":true,"variant":"Chocolat","change":"Avec du cacao et un carré de chocolat au centre."},{"title":"Mug cake au cacao","intro":"Le gâteau express pour une envie de chocolat.","minutes":5,"calories":380,"difficulty":"Facile","imageSearch":"chocolate mug cake","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":100,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"cacao en poudre","plural":"cacao en poudre","qty":4,"unit":"c. à s.","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"lait","plural":"laits","qty":12,"unit":"cl","have":false},{"name":"huile de tournesol","plural":"huile de tournesol","qty":6,"unit":"c. à s.","have":false}],"steps":[{"text":"Mélange la farine, le sucre et le cacao.","timer":null},{"text":"Ajoute les œufs, le lait et l'huile et mélange.","timer":null},{"text":"Répartis dans 4 tasses.","timer":null},{"text":"Fais cuire chaque tasse 1 min 30 au micro-ondes.","timer":{"label":"Micro-ondes","min":2}}],"kids":true,"dessert":true,"variant":"Mug cake","change":"Un vrai petit gâteau au chocolat, cuit dans une tasse."}]$r$::jsonb, 'claude')
