insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('welsh', 'Welsh', array['welsh rarebit', 'welsh ch ti', 'welsh lilloi']::text[], 'dish', $r$[{"title":"Welsh","intro":"Le plat du Nord : pain et jambon nappés de cheddar fondu à la bière, avec un œuf.","minutes":30,"calories":850,"difficulty":"Facile","imageSearch":"welsh rarebit","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Nord","serves":4,"items":[{"name":"cheddar","plural":"cheddar","qty":500,"unit":"g","have":false},{"name":"bière blonde","plural":"bière blonde","qty":20,"unit":"cl","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à s.","have":false},{"name":"pain de campagne","plural":"pains de campagne","qty":4,"unit":"tranches","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four en position gril.","timer":null},{"text":"Fais fondre le cheddar en morceaux avec la bière et la moutarde à feu doux, en remuant.","timer":null},{"text":"Pose une tranche de pain dans chaque plat individuel et ajoute le jambon.","timer":null},{"text":"Nappe de cheddar fondu et fais gratiner 8 min.","timer":{"label":"Four","min":8}},{"text":"Pose un œuf au plat sur chaque welsh.","timer":null}],"variant":"La classique","change":""},{"title":"Welsh sans bière","intro":"Un welsh plus doux, pour toute la famille.","minutes":30,"calories":800,"difficulty":"Facile","imageSearch":"cheddar toast melted cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cheddar","plural":"cheddar","qty":500,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à c.","have":false},{"name":"pain de campagne","plural":"pains de campagne","qty":4,"unit":"tranches","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false}],"steps":[{"text":"Fais fondre le cheddar avec le lait et la moutarde à feu doux.","timer":null},{"text":"Pose le pain et le jambon dans des plats individuels.","timer":null},{"text":"Nappe de cheddar et fais gratiner 8 min.","timer":{"label":"Four","min":8}},{"text":"Ajoute un œuf au plat.","timer":null}],"kids":true,"variant":"Sans alcool","change":"La bière est remplacée par du lait."},{"title":"Welsh végétarien","intro":"Un welsh sans viande, aux champignons poêlés.","minutes":30,"calories":760,"difficulty":"Facile","imageSearch":"vegetarian welsh rarebit mushrooms","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cheddar","plural":"cheddar","qty":500,"unit":"g","have":false},{"name":"bière blonde","plural":"bière blonde","qty":20,"unit":"cl","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à s.","have":false},{"name":"pain de campagne","plural":"pains de campagne","qty":4,"unit":"tranches","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false}],"steps":[{"text":"Fais revenir les champignons émincés 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Fais fondre le cheddar avec la bière et la moutarde.","timer":null},{"text":"Pose le pain et les champignons dans des plats, nappe de cheddar.","timer":null},{"text":"Fais gratiner 8 min et ajoute un œuf au plat.","timer":{"label":"Four","min":8}}],"variant":"Végétarien","change":"Sans jambon, avec des champignons."}]$r$::jsonb, 'claude')
