insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('fondue savoyarde', 'Fondue savoyarde', array['fondue', 'fondue au fromage', 'fondue fromage']::text[], 'dish', $r$[{"title":"Fondue savoyarde","intro":"Les trois fromages fondus au vin blanc, où l'on trempe des cubes de pain.","minutes":30,"calories":820,"difficulty":"Moyen","imageSearch":"cheese fondue","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spécialité savoyarde","serves":4,"items":[{"name":"comté râpé","plural":"comté râpé","qty":300,"unit":"g","have":false},{"name":"beaufort","plural":"beaufort","qty":300,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":200,"unit":"g","have":false},{"name":"vin blanc sec","plural":"vin blanc sec","qty":40,"unit":"cl","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false},{"name":"pain de campagne","plural":"pains de campagne","qty":1,"unit":"","have":false}],"steps":[{"text":"Coupe le pain en cubes, la veille si possible.","timer":null},{"text":"Frotte le caquelon avec l'ail.","timer":null},{"text":"Chauffe le vin dans le caquelon, puis ajoute les fromages petit à petit en remuant en huit.","timer":null},{"text":"Délaye la fécule dans un peu de vin et ajoute-la pour lier.","timer":null},{"text":"Pose le caquelon sur le réchaud et trempe le pain avec les piques.","timer":null}],"variant":"La classique","change":""},{"title":"Fondue au fromage sans alcool","intro":"Une fondue pour toute la famille, sans vin.","minutes":30,"calories":780,"difficulty":"Moyen","imageSearch":"family cheese fondue","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"comté râpé","plural":"comté râpé","qty":300,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":300,"unit":"g","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"pain de campagne","plural":"pains de campagne","qty":1,"unit":"","have":false}],"steps":[{"text":"Prépare 35 cl de bouillon et ajoute le jus du citron.","timer":null},{"text":"Frotte le caquelon d'ail et chauffe le bouillon dedans.","timer":null},{"text":"Ajoute les fromages petit à petit en remuant, puis la fécule délayée.","timer":null},{"text":"Sers avec le pain en cubes.","timer":null}],"kids":true,"variant":"Sans vin","change":"Le vin est remplacé par du bouillon et du jus de citron."},{"title":"Fondue aux champignons","intro":"Une fondue forestière aux champignons.","minutes":35,"calories":840,"difficulty":"Moyen","imageSearch":"mushroom cheese fondue","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"comté râpé","plural":"comté râpé","qty":300,"unit":"g","have":false},{"name":"beaufort","plural":"beaufort","qty":300,"unit":"g","have":false},{"name":"vin blanc sec","plural":"vin blanc sec","qty":40,"unit":"cl","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":250,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":1,"unit":"c. à s.","have":false},{"name":"pain de campagne","plural":"pains de campagne","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais revenir les champignons émincés 8 min et hache-les grossièrement.","timer":{"label":"Poêle","min":8}},{"text":"Chauffe le vin dans le caquelon frotté d'ail.","timer":null},{"text":"Ajoute les fromages petit à petit, puis la fécule délayée.","timer":null},{"text":"Ajoute les champignons et sers avec le pain.","timer":null}],"variant":"Champignons","change":"Avec des cèpes ou des champignons poêlés."}]$r$::jsonb, 'claude')
