insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('croziflette', 'Croziflette', array['crozet', 'gratin de crozet', 'crozet savoyard']::text[], 'dish', $r$[{"title":"Croziflette","intro":"Comme une tartiflette, mais avec des crozets, ces petites pâtes carrées de Savoie.","minutes":50,"calories":780,"difficulty":"Facile","imageSearch":"croziflette crozets reblochon","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité savoyarde","serves":4,"items":[{"name":"crozets","plural":"crozets","qty":400,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":200,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais cuire les crozets 15 min à l'eau salée.","timer":{"label":"Cuisson","min":15}},{"text":"Fais dorer les lardons et les oignons émincés, puis déglace au vin blanc.","timer":{"label":"Poêle","min":8}},{"text":"Mélange les crozets, les lardons, les oignons et la crème dans un plat.","timer":null},{"text":"Pose le reblochon coupé en deux, croûte dessus.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"La classique","change":""},{"title":"Gratin de crozets au jambon","intro":"Un gratin de crozets plus doux, au jambon.","minutes":45,"calories":680,"difficulty":"Facile","imageSearch":"crozets gratin ham","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"crozets","plural":"crozets","qty":400,"unit":"g","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":25,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais cuire les crozets 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Fais fondre l'oignon émincé.","timer":null},{"text":"Mélange les crozets, le jambon en dés, l'oignon et la crème dans un plat.","timer":null},{"text":"Couvre d'emmental et enfourne 20 min.","timer":{"label":"Four","min":20}}],"kids":true,"variant":"Au jambon","change":"Avec du jambon et de l'emmental."},{"title":"Croziflette végétarienne","intro":"La croziflette sans viande, aux champignons.","minutes":50,"calories":700,"difficulty":"Facile","imageSearch":"vegetarian croziflette","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"crozets","plural":"crozets","qty":400,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Fais cuire les crozets 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Fais revenir les champignons et les oignons émincés.","timer":{"label":"Poêle","min":10}},{"text":"Mélange tout avec la crème dans un plat et pose le reblochon.","timer":null},{"text":"Enfourne 20 min à 200 °C.","timer":{"label":"Four","min":20}}],"variant":"Végétarienne","change":"Avec des champignons à la place des lardons."}]$r$::jsonb, 'claude')
