insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pissaladiere', 'Pissaladière', array['pissaladiere nicoise', 'tarte aux oignon', 'tarte a l oignon']::text[], 'dish', $r$[{"title":"Pissaladière","intro":"La tarte niçoise aux oignons fondus, aux anchois et aux olives noires.","minutes":80,"calories":380,"difficulty":"Moyen","imageSearch":"pissaladiere","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité niçoise","serves":4,"items":[{"name":"pâte à pizza","plural":"pâtes à pizza","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1000,"unit":"g","have":false},{"name":"anchois à l'huile","plural":"anchois à l'huile","qty":12,"unit":"","have":false},{"name":"olives noires","plural":"olives noires","qty":16,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false}],"steps":[{"text":"Émince finement les oignons.","timer":null},{"text":"Fais-les fondre 40 min à feu doux dans l'huile avec le thym, sans les colorer.","timer":{"label":"Cuisson","min":40}},{"text":"Préchauffe le four à 220 °C et étale la pâte sur une plaque.","timer":null},{"text":"Étale les oignons, dessine des croisillons d'anchois et pose les olives.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"La classique","change":""},{"title":"Tarte à l'oignon alsacienne","intro":"La tarte à l'oignon crémeuse d'Alsace.","minutes":70,"calories":420,"difficulty":"Moyen","imageSearch":"alsatian onion tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité alsacienne","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":800,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"muscade","plural":"muscade","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais fondre les oignons émincés 25 min dans le beurre.","timer":{"label":"Cuisson","min":25}},{"text":"Préchauffe le four à 200 °C et garnis un moule de pâte.","timer":null},{"text":"Bats les œufs avec la crème, le sel, le poivre et la muscade.","timer":null},{"text":"Étale les oignons sur la pâte et verse le mélange.","timer":null},{"text":"Enfourne 30 min.","timer":{"label":"Four","min":30}}],"variant":"Alsacienne","change":"Les oignons sont liés avec des œufs et de la crème."},{"title":"Pissaladière sans anchois","intro":"Une pissaladière végétarienne aux oignons et olives.","minutes":80,"calories":350,"difficulty":"Moyen","imageSearch":"onion olive tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte à pizza","plural":"pâtes à pizza","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1000,"unit":"g","have":false},{"name":"olives noires","plural":"olives noires","qty":20,"unit":"","have":false},{"name":"tomates séchées","plural":"tomates séchées","qty":60,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais fondre les oignons émincés 40 min à feu doux avec l'huile et le thym.","timer":{"label":"Cuisson","min":40}},{"text":"Préchauffe le four à 220 °C et étale la pâte.","timer":null},{"text":"Étale les oignons, ajoute les olives et les tomates séchées en lanières.","timer":null},{"text":"Enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"Végétarienne","change":"Sans anchois, avec des tomates séchées."}]$r$::jsonb, 'claude')
