insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('daube provencale', 'Daube provençale', array['daube', 'daube de boeuf', 'boeuf en daube']::text[], 'dish', $r$[{"title":"Daube provençale","intro":"Le bœuf mariné au vin rouge et mijoté longtemps avec orange et olives.","minutes":210,"calories":580,"difficulty":"Moyen","imageSearch":"provencal beef daube","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité provençale","serves":4,"items":[{"name":"bœuf à braiser","plural":"bœuf à braiser","qty":1200,"unit":"g","have":false},{"name":"vin rouge","plural":"vin rouge","qty":75,"unit":"cl","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":150,"unit":"g","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"olives noires","plural":"olives noires","qty":80,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais mariner le bœuf en morceaux une nuit dans le vin avec les carottes, les oignons, l'ail, le bouquet garni et le zeste de l'orange.","timer":null},{"text":"Égoutte la viande et fais-la dorer avec les lardons dans une cocotte.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute la marinade et porte à frémissement.","timer":null},{"text":"Couvre et laisse mijoter 3 h à feu très doux.","timer":{"label":"Cuisson","min":180}},{"text":"Ajoute les olives 15 min avant la fin.","timer":null}],"variant":"La classique","change":""},{"title":"Daube provençale express","intro":"Toute la saveur de la daube, en une heure.","minutes":75,"calories":560,"difficulty":"Facile","imageSearch":"beef stew red wine olives","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"bœuf à braiser","plural":"bœuf à braiser","qty":1000,"unit":"g","have":false},{"name":"vin rouge","plural":"vin rouge","qty":50,"unit":"cl","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"olives noires","plural":"olives noires","qty":80,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false}],"steps":[{"text":"Fais dorer le bœuf en morceaux dans la cocotte-minute.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les oignons, les carottes, l'ail, le vin et le zeste de l'orange.","timer":null},{"text":"Ferme et compte 50 min après le sifflement.","timer":{"label":"Cuisson","min":50}},{"text":"Ajoute les olives et laisse 5 min sans couvercle.","timer":null}],"variant":"À la cocotte-minute","change":"Sans marinade, cuite à la cocotte-minute."},{"title":"Daube de joue de bœuf","intro":"Une daube ultra fondante à la joue de bœuf.","minutes":240,"calories":560,"difficulty":"Moyen","imageSearch":"braised beef cheeks","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"joue de bœuf","plural":"joues de bœuf","qty":1200,"unit":"g","have":false},{"name":"vin rouge","plural":"vin rouge","qty":75,"unit":"cl","have":false},{"name":"carotte","plural":"carottes","qty":3,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":200,"unit":"g","have":false},{"name":"orange","plural":"oranges","qty":1,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais dorer les joues en morceaux dans une cocotte.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les oignons, les carottes, les tomates, le vin, le zeste et le bouquet garni.","timer":null},{"text":"Couvre et laisse mijoter 3 h 30 à feu très doux.","timer":{"label":"Cuisson","min":210}},{"text":"Sers avec des pâtes fraîches ou de la purée.","timer":null}],"variant":"Joue de bœuf","change":"Avec de la joue de bœuf, encore plus fondante."}]$r$::jsonb, 'claude')
