insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('piperade', 'Piperade', array['piperade basquaise', 'poivron a la basquaise']::text[], 'dish', $r$[{"title":"Piperade","intro":"Les poivrons et tomates fondus du Pays basque, avec du jambon de Bayonne.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"piperade basque","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité basque","serves":4,"items":[{"name":"poivron vert","plural":"poivrons verts","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":5,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"jambon de Bayonne","plural":"jambon de Bayonne","qty":4,"unit":"tranches","have":false},{"name":"piment d'Espelette","plural":"piment d'Espelette","qty":1,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Émince les oignons et les poivrons, et coupe les tomates en dés.","timer":null},{"text":"Fais fondre les oignons et les poivrons 15 min dans l'huile.","timer":{"label":"Poêle","min":15}},{"text":"Ajoute les tomates, l'ail et le piment d'Espelette, et laisse 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Fais griller le jambon quelques secondes à la poêle et pose-le sur la piperade.","timer":null}],"variant":"La classique","change":""},{"title":"Piperade aux œufs","intro":"La piperade avec ses œufs, en plat complet.","minutes":40,"calories":300,"difficulty":"Facile","imageSearch":"piperade eggs","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poivron vert","plural":"poivrons verts","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":5,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":6,"unit":"","have":false},{"name":"piment d'Espelette","plural":"piment d'Espelette","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Fais fondre les oignons et les poivrons émincés 15 min.","timer":{"label":"Poêle","min":15}},{"text":"Ajoute les tomates et le piment, et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Verse les œufs battus et remue doucement jusqu'à ce qu'ils soient crémeux.","timer":null},{"text":"Sers aussitôt.","timer":null}],"variant":"Aux œufs","change":"Des œufs brouillés dans la piperade."},{"title":"Piperade végétarienne","intro":"La piperade végétarienne servie avec du riz.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"vegetarian piperade rice","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"poivron vert","plural":"poivrons verts","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":5,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"piment d'Espelette","plural":"piment d'Espelette","qty":1,"unit":"c. à c.","have":false},{"name":"riz","plural":"riz","qty":200,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Fais fondre les oignons et les poivrons 15 min.","timer":{"label":"Poêle","min":15}},{"text":"Ajoute les tomates, l'ail et le piment, et laisse 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Sers avec le riz.","timer":null}],"variant":"Végétarienne","change":"Sans jambon, avec du riz."}]$r$::jsonb, 'claude')
