insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('spaghetti alle vongole', 'Spaghetti alle vongole', array['spaghetti aux palourde', 'pate aux palourde', 'vongole', 'pate aux fruit de mer', 'spaghetti fruit de mer']::text[], 'dish', $r$[{"title":"Spaghetti aux palourdes","intro":"Les spaghetti italiens aux palourdes, ail, vin blanc et persil.","minutes":30,"calories":480,"difficulty":"Moyen","imageSearch":"spaghetti alle vongole","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"palourdes","plural":"palourdes","qty":1000,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":4,"unit":"c. à s.","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais tremper les palourdes 30 min dans de l'eau salée pour retirer le sable.","timer":null},{"text":"Fais cuire les spaghetti.","timer":{"label":"Cuisson","min":9}},{"text":"Fais revenir l'ail et le piment dans l'huile, ajoute les palourdes et le vin, et couvre.","timer":null},{"text":"Retire du feu dès qu'elles s'ouvrent.","timer":{"label":"Cuisson","min":4}},{"text":"Mélange les spaghetti avec les palourdes et le persil.","timer":null}],"variant":"La classique","change":""},{"title":"Pâtes aux fruits de mer","intro":"Des pâtes aux fruits de mer en sauce tomate, faciles.","minutes":25,"calories":500,"difficulty":"Facile","imageSearch":"seafood pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"fruits de mer surgelés","plural":"fruits de mer surgelés","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les spaghetti.","timer":{"label":"Cuisson","min":9}},{"text":"Fais revenir l'ail, ajoute les fruits de mer et le vin, et laisse 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute les tomates et laisse 8 min.","timer":{"label":"Cuisson","min":8}},{"text":"Mélange aux pâtes et parsème de persil.","timer":null}],"variant":"Fruits de mer","change":"Avec un mélange de fruits de mer surgelés et de la tomate."},{"title":"Spaghetti aux moules","intro":"La version plus accessible, avec des moules.","minutes":30,"calories":480,"difficulty":"Moyen","imageSearch":"mussel spaghetti","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"moule","plural":"moules","qty":1000,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false},{"name":"tomate cerise","plural":"tomates cerises","qty":200,"unit":"g","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les spaghetti.","timer":{"label":"Cuisson","min":9}},{"text":"Fais ouvrir les moules avec l'ail et le vin à couvert.","timer":{"label":"Cuisson","min":5}},{"text":"Décortique-en la moitié et ajoute les tomates cerises.","timer":null},{"text":"Mélange aux spaghetti avec le persil.","timer":null}],"variant":"Aux moules","change":"Les moules remplacent les palourdes."}]$r$::jsonb, 'claude')
