insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('cannelloni', 'Cannellonis', array['cannelloni ricotta epinard', 'cannelloni a la viande']::text[], 'dish', $r$[{"title":"Cannellonis ricotta-épinards","intro":"Des tubes de pâtes farcis à la ricotta et aux épinards, gratinés à la tomate.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"spinach ricotta cannelloni","veg":true,"oven":true,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"cannellonis","plural":"cannellonis","qty":16,"unit":"","have":false},{"name":"ricotta","plural":"ricottas","qty":500,"unit":"g","have":false},{"name":"épinards surgelés","plural":"épinards surgelés","qty":400,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":600,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":50,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Fais décongeler les épinards et presse-les.","timer":null},{"text":"Mélange-les avec la ricotta, l'œuf, la moitié du parmesan, sel et poivre.","timer":null},{"text":"Remplis les cannellonis avec une poche ou une petite cuillère.","timer":null},{"text":"Étale la moitié des tomates dans un plat, range les cannellonis et couvre du reste.","timer":null},{"text":"Ajoute la mozzarella et le parmesan, et enfourne 35 min.","timer":{"label":"Four","min":35}}],"variant":"La classique","change":""},{"title":"Cannellonis à la viande","intro":"Les cannellonis comme des lasagnes roulées, à la viande.","minutes":70,"calories":620,"difficulty":"Moyen","imageSearch":"meat cannelloni bechamel","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cannellonis","plural":"cannellonis","qty":16,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":500,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false}],"steps":[{"text":"Fais revenir l'oignon et le bœuf, ajoute la moitié des tomates et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Prépare une béchamel avec le beurre, la farine et le lait.","timer":null},{"text":"Remplis les cannellonis de viande et range-les dans un plat sur le reste des tomates.","timer":null},{"text":"Nappe de béchamel et d'emmental.","timer":null},{"text":"Enfourne 35 min à 180 °C.","timer":{"label":"Four","min":35}}],"kids":true,"variant":"À la viande","change":"Farcis de bœuf haché à la tomate, sous la béchamel."},{"title":"Cannellonis au saumon","intro":"Des cannellonis délicats au saumon et à l'aneth.","minutes":60,"calories":540,"difficulty":"Moyen","imageSearch":"salmon cannelloni","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cannellonis","plural":"cannellonis","qty":16,"unit":"","have":false},{"name":"pavé de saumon","plural":"pavés de saumon","qty":2,"unit":"","have":false},{"name":"ricotta","plural":"ricottas","qty":400,"unit":"g","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":25,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesans","qty":50,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le saumon 10 min à la vapeur et émiette-le.","timer":{"label":"Cuisson","min":10}},{"text":"Mélange-le avec la ricotta et l'aneth.","timer":null},{"text":"Remplis les cannellonis et range-les dans un plat.","timer":null},{"text":"Nappe de crème et de parmesan, et enfourne 30 min à 180 °C.","timer":{"label":"Four","min":30}}],"variant":"Au saumon","change":"Farcis au saumon et à la ricotta."}]$r$::jsonb, 'claude')
