ans","qty":50,"unit":"g","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":200,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":100,"unit":"g","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Prépare un risotto au parmesan et laisse-le refroidir.","timer":{"label":"Cuisson","min":18}},{"text":"Fais une petite bolognaise épaisse avec le bœuf et les tomates.","timer":{"label":"Cuisson","min":15}},{"text":"Forme des boules de riz avec un peu de bolognaise au centre.","timer":null},{"text":"Pane-les à l'œuf et à la chapelure, et fais-les frire 4 min.","timer":{"label":"Friture","min":4}}],"variant":"À la viande","change":"Avec un cœur de sauce bolognaise."},{"title":"Arancini au four","intro":"Des arancini plus légers, dorés au four.","minutes":80,"calories":350,"difficulty":"Moyen","imageSearch":"baked arancini","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"riz à risotto","plural":"riz à risotto","qty":300,"unit":"g","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":60,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":100,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Prépare un risotto au parmesan et laisse-le refroidir.","timer":{"label":"Cuisson","min":18}},{"text":"Forme des boules avec un dé de mozzarella au centre.","timer":null},{"text":"Pane-les à l'œuf et à la chapelure, et arrose d'huile.","timer":null},{"text":"En