tron","plural":"citrons","qty":1,"unit":"","have":false}],"steps":[{"text":"Sèche bien les calamars.","timer":null},{"text":"Fais-les sauter 3 min à feu très vif dans l'huile.","timer":{"label":"Poêle","min":3}},{"text":"Ajoute l'ail haché et le persil, et laisse 1 min.","timer":null},{"text":"Arrose de jus de citron.","timer":null}],"variant":"Sautés","change":"Sautés à la poêle, sans friture."},{"title":"Calamars à la tomate","intro":"Des encornets fondants à la sauce tomate.","minutes":50,"calories":280,"difficulty":"Facile","imageSearch":"calamari tomato stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"anneaux de calamars","plural":"anneaux de calamars","qty":600,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et l'ail.","timer":null},{"text":"Ajoute les calamars et fais-les revenir 3 min.","timer":null},{"text":"Ajoute le vin et les tomates, et laisse mijoter 35 min.","timer":{"label":"Cuisson","min":35}},{"text":"Parsème de persil et sers avec du riz ou des pâtes.","timer":null}],"variant":"À la tomate","change":"Mijotés dans une sauce tomate."}]$r$::jsonb, 'claude')
