insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('rillette de thon', 'Rillettes de thon', array['rillette de poisson', 'rillette de sardine', 'rillette de saumon', 'tartinade de thon']::text[], 'dish', $r$[{"title":"Rillettes de thon","intro":"Le thon écrasé au fromage frais et au citron, à tartiner pour l'apéritif.","minutes":10,"calories":180,"difficulty":"Facile","imageSearch":"tuna rillettes","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"thon au naturel","plural":"thon au naturel","qty":280,"unit":"g","have":false},{"name":"fromage frais","plural":"fromage frais","qty":150,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"ciboulette","plural":"ciboulette","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Égoutte le thon.","timer":null},{"text":"Écrase-le à la fourchette avec le fromage frais.","timer":null},{"text":"Ajoute le jus du citron, la ciboulette ciselée et du poivre.","timer":null},{"text":"Garde au frais et sers avec du pain grillé.","timer":null}],"variant":"La classique","change":""},{"title":"Rillettes de sardines","intro":"Des rillettes de sardines au beurre et citron.","minutes":10,"calories":220,"difficulty":"Facile","imageSearch":"sardine rillettes","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"sardines à l'huile","plural":"sardines à l'huile","qty":2,"unit":"","have":false},{"name":"fromage frais","plural":"fromage frais","qty":100,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"persil","plural":"persil","qty":null,"unit":"","have":false}],"steps":[{"text":"Égoutte les sardines et retire l'arête centrale.","timer":null},{"text":"Écrase-les avec le fromage frais.","timer":null},{"text":"Ajoute le jus du citron, l'échalote hachée et le persil.","timer":null},{"text":"Garde au frais.","timer":null}],"variant":"Sardines","change":"Avec des sardines à l'huile."},{"title":"Rillettes de saumon","intro":"Les rillettes de saumon des apéritifs de fête.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"salmon rillettes","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"pavé de saumon","plural":"pavés de saumon","qty":1,"unit":"","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":2,"unit":"tranches","have":false},{"name":"fromage frais","plural":"fromage frais","qty":150,"unit":"g","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire le saumon 8 min à la vapeur et laisse refroidir.","timer":{"label":"Cuisson","min":8}},{"text":"Émiette-le et coupe le saumon fumé en petits morceaux.","timer":null},{"text":"Mélange avec le fromage frais, le jus du citron et l'aneth.","timer":null},{"text":"Garde au frais 1 h.","timer":null}],"variant":"Saumon","change":"Avec du saumon frais et du saumon fumé."}]$r$::jsonb, 'claude')
