insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('steak de thon', 'Steak de thon', array['thon mi cuit', 'pave de thon', 'thon grille', 'thon frai']::text[], 'dish', $r$[{"title":"Steak de thon mi-cuit","intro":"Le thon rouge saisi au sésame, rosé à cœur, avec une sauce soja.","minutes":15,"calories":320,"difficulty":"Moyen","imageSearch":"seared tuna steak sesame","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"steak de thon","plural":"steaks de thon","qty":4,"unit":"","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":4,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"huile","plural":"huile","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Enrobe les steaks de graines de sésame.","timer":null},{"text":"Saisis-les 1 min de chaque côté à feu très vif.","timer":{"label":"Poêle","min":2}},{"text":"Coupe-les en tranches.","timer":null},{"text":"Sers avec la sauce soja mélangée au jus du citron vert.","timer":null}],"variant":"La classique","change":""},{"title":"Thon à la provençale","intro":"Le thon mijoté à la tomate, aux olives et aux câpres.","minutes":30,"calories":350,"difficulty":"Facile","imageSearch":"tuna provencal tomato","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"steak de thon","plural":"steaks de thon","qty":4,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"olives noires","plural":"olives noires","qty":60,"unit":"g","have":false},{"name":"câpres","plural":"câpres","qty":1,"unit":"c. à s.","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false}],"steps":[{"text":"Fais revenir l'oignon et l'ail.","timer":null},{"text":"Ajoute les tomates, les olives et les câpres, et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Saisis le thon 1 min de chaque côté, puis mets-le dans la sauce.","timer":null},{"text":"Laisse 5 min à couvert.","timer":{"label":"Cuisson","min":5}}],"variant":"À la tomate","change":"Cuit dans une sauce tomate aux olives."},{"title":"Thon grillé à la mangue","intro":"Un thon grillé frais et exotique.","minutes":20,"calories":380,"difficulty":"Facile","imageSearch":"grilled tuna mango salsa","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"steak de thon","plural":"steaks de thon","qty":4,"unit":"","have":false},{"name":"mangue","plural":"mangues","qty":1,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe la mangue, l'avocat et l'oignon en petits dés.","timer":null},{"text":"Mélange avec le jus du citron vert et la coriandre.","timer":null},{"text":"Grille le thon 2 min de chaque côté.","timer":{"label":"Poêle","min":4}},{"text":"Sers avec la salsa.","timer":null}],"variant":"Mangue","change":"Avec une salsa de mangue et d'avocat."}]$r$::jsonb, 'claude')
