insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('lotte a l armoricaine', 'Lotte à l''armoricaine', array['lotte', 'lotte armoricaine', 'sauce armoricaine']::text[], 'dish', $r$[{"title":"Lotte à l'armoricaine","intro":"La lotte en sauce tomate au vin blanc et au cognac, à la bretonne.","minutes":45,"calories":380,"difficulty":"Moyen","imageSearch":"monkfish armoricaine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité bretonne","serves":4,"items":[{"name":"lotte","plural":"lottes","qty":800,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":3,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"vin blanc","plural":"vin blanc","qty":20,"unit":"cl","have":false},{"name":"cognac","plural":"cognac","qty":3,"unit":"c. à s.","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe la lotte en médaillons et fais-les dorer 3 min. Flambe au cognac.","timer":{"label":"Poêle","min":3}},{"text":"Retire la lotte et fais revenir les échalotes et l'ail.","timer":null},{"text":"Ajoute le vin et les tomates, et laisse réduire 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute la crème, remets la lotte et laisse 8 min.","timer":{"label":"Cuisson","min":8}}],"variant":"La classique","change":""},{"title":"Lotte à la crème et au safran","intro":"Des médaillons de lotte dans une sauce dorée au safran.","minutes":35,"calories":400,"difficulty":"Moyen","imageSearch":"monkfish saffron cream","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lotte","plural":"lottes","qty":800,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vin blanc","qty":10,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"safran","plural":"safran","qty":null,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false}],"steps":[{"text":"Fais dorer la lotte en médaillons dans le beurre et retire-la.","timer":{"label":"Poêle","min":4}},{"text":"Fais revenir les échalotes, déglace au vin blanc.","timer":null},{"text":"Ajoute la crème et le safran, et laisse réduire 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Remets la lotte et laisse 6 min.","timer":{"label":"Cuisson","min":6}}],"variant":"Safran","change":"Une sauce crème au safran, sans tomate."},{"title":"Cabillaud à l'armoricaine","intro":"La sauce armoricaine avec du cabillaud, moins cher.","minutes":35,"calories":340,"difficulty":"Facile","imageSearch":"cod tomato wine sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dos de cabillaud","plural":"dos de cabillaud","qty":4,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vin blanc","qty":15,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Fais revenir les échalotes, ajoute le vin et les tomates.","timer":null},{"text":"Laisse réduire 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute la crème.","timer":null},{"text":"Pose le cabillaud dans la sauce, couvre et laisse 8 min.","timer":{"label":"Cuisson","min":8}}],"variant":"Cabillaud","change":"Le cabillaud remplace la lotte."}]$r$::jsonb, 'claude')
