"name":"herbes de Provence","plural":"herbes de Provence","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Mets les courgettes en rondelles et les tomates dans un plat avec l'huile et les herbes.","timer":null},{"text":"Enfourne 15 min.","timer":{"label":"Four","min":15}},{"text":"Ajoute le colin, arrose de citron et remets 12 min.","timer":{"label":"Four","min":12}}],"variant":"Au four","change":"Cuit au four avec des légumes."},{"title":"Colin pané","intro":"Du poisson pané maison, que les enfants adorent.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"breaded hake fillet","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filet de colin","plural":"filets de colin","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":80,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":3,"unit":"c. à s.","have":false},{"name":"huile","plural":"huile","qty":4,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false}],"steps":[{"text":"Passe les filets dans la farine, l'œuf battu, puis la chapelure.","timer":null},{"text":"Fais-les dorer 4 min de chaque côté dans l'huile.","timer":{"label":"Poêle","min":8}},{"text":"Égoutte sur du papier absorbant.","timer":null},{"text":"Sers avec des quartiers de citron.","timer":null}],"kids":true,"variant":"Pané","change":"Des filets panés et dorés à la poêle."}]$r$::jsonb, 'claude')
