lse},{"name":"pois chiche","plural":"pois chiches","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ras el-hanout","plural":"ras el-hanout","qty":2,"unit":"c. à c.","have":false}],"steps":[{"text":"Fais dorer l'agneau avec les oignons.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les épices, les carottes et 40 cl d'eau, et laisse mijoter 1 h.","timer":{"label":"Cuisson","min":60}},{"text":"Ajoute les courgettes et les pois chiches.","timer":null},{"text":"Laisse 25 min.","timer":{"label":"Cuisson","min":25}}],"variant":"Aux légumes","change":"Avec carottes, courgettes et pois chiches."},{"title":"Tajine d'agneau aux abricots","intro":"Un tajine sucré-salé aux abricots.","minutes":120,"calories":600,"difficulty":"Moyen","imageSearch":"lamb apricot tagine","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"épaule d'agneau","plural":"épaules d'agneau","qty":1000,"unit":"g","have":false},{"name":"abricots secs","plural":"abricots secs","qty":150,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer l'agneau avec les oignons.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les épices et 40 cl d'eau, et laisse mijoter 1 h 15.","timer":{"label":"Cuisson","min":75}},{"text":"Ajoute les abricots et laisse 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Parsème de coriandre.","timer":null}],"variant":"Abricots","change":"Avec des abricots secs."}]$r$::jsonb, 'claude')
