insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('brochette de poulet', 'Brochettes de poulet', array['brochette', 'brochette barbecue', 'brochette de dinde']::text[], 'dish', $r$[{"title":"Brochettes de poulet marinées","intro":"Des brochettes de poulet marinées au citron et au paprika, avec poivrons et oignons.","minutes":45,"calories":350,"difficulty":"Facile","imageSearch":"grilled chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"c. à c.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false}],"steps":[{"text":"Coupe le poulet en cubes et fais-le mariner 20 min avec l'huile, le citron, le paprika et l'ail.","timer":{"label":"Repos","min":20}},{"text":"Coupe le poivron et l'oignon en morceaux.","timer":null},{"text":"Enfile poulet et légumes en alternant sur des brochettes.","timer":null},{"text":"Fais-les griller 12 min en les retournant.","timer":{"label":"Poêle","min":12}}],"kids":true,"variant":"La classique","change":""},{"title":"Brochettes de poulet au yaourt","intro":"Des brochettes tendres et parfumées, avec une sauce yaourt.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"yogurt marinated chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":2,"unit":"","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"concombre","plural":"concombres","qty":1,"unit":"","have":false}],"steps":[{"text":"Mélange 1 yaourt avec le curry, le jus du citron et l'ail.","timer":null},{"text":"Fais mariner le poulet en cubes 30 min.","timer":{"label":"Repos","min":30}},{"text":"Enfile sur des brochettes et fais griller 12 min.","timer":{"label":"Poêle","min":12}},{"text":"Sers avec l'autre yaourt mélangé au concombre râpé.","timer":null}],"variant":"Au yaourt","change":"Marinées au yaourt et aux épices, à l'indienne."},{"title":"Brochettes de poulet au miel","intro":"Des brochettes sucrées-salées qui plaisent aux enfants.","minutes":40,"calories":360,"difficulty":"Facile","imageSearch":"honey soy chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"miel","plural":"miels","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à s.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais mariner le poulet en cubes 20 min avec le miel et la sauce soja.","timer":{"label":"Repos","min":20}},{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Enfile sur des brochettes et fais griller 12 min en arrosant de marinade.","timer":{"label":"Poêle","min":12}},{"text":"Parsème de sésame.","timer":null}],"kids":true,"variant":"Au miel","change":"Laquées au miel et à la sauce soja."}]$r$::jsonb, 'claude')
