insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet tandoori', 'Poulet tandoori', array['tandoori', 'poulet tandori', 'cuisse tandoori']::text[], 'dish', $r$[{"title":"Poulet tandoori","intro":"Des cuisses de poulet marinées au yaourt et aux épices tandoori, rôties au four.","minutes":60,"calories":420,"difficulty":"Facile","imageSearch":"tandoori chicken","veg":false,"oven":true,"cold":false,"missing":"","origin":"Recette indienne","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":2,"unit":"","have":false},{"name":"épices tandoori","plural":"épices tandoori","qty":2,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"gingembre","plural":"gingembre","qty":1,"unit":"c. à c.","have":false},{"name":"riz basmati","plural":"riz basmati","qty":250,"unit":"g","have":false}],"steps":[{"text":"Entaille les cuisses et fais-les mariner au moins 1 h avec le yaourt, les épices, le citron, l'ail et le gingembre.","timer":{"label":"Repos","min":60}},{"text":"Préchauffe le four à 220 °C.","timer":null},{"text":"Pose les cuisses sur une plaque et enfourne 40 min.","timer":{"label":"Four","min":40}},{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}}],"variant":"La classique","change":""},{"title":"Brochettes de poulet tandoori","intro":"Des brochettes tandoori rapides à griller.","minutes":40,"calories":360,"difficulty":"Facile","imageSearch":"tandoori chicken skewers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"épices tandoori","plural":"épices tandoori","qty":2,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais mariner le poulet en cubes 30 min avec le yaourt, les épices et le citron.","timer":{"label":"Repos","min":30}},{"text":"Enfile-le sur des brochettes avec l'oignon en morceaux.","timer":null},{"text":"Fais griller 12 min en les retournant.","timer":{"label":"Poêle","min":12}},{"text":"Sers avec une salade.","timer":null}],"variant":"En brochettes","change":"Des cubes de blanc de poulet en brochettes."},{"title":"Chou-fleur tandoori","intro":"La marinade tandoori sur un chou-fleur rôti.","minutes":50,"calories":220,"difficulty":"Facile","imageSearch":"tandoori cauliflower","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chou-fleur","plural":"choux-fleurs","qty":1,"unit":"","have":false},{"name":"yaourt nature","plural":"yaourts nature","qty":1,"unit":"","have":false},{"name":"épices tandoori","plural":"épices tandoori","qty":2,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 210 °C.","timer":null},{"text":"Coupe le chou-fleur en fleurettes et enrobe-les du yaourt mélangé aux épices et au citron.","timer":null},{"text":"Enfourne 35 min.","timer":{"label":"Four","min":35}},{"text":"Parsème de coriandre.","timer":null}],"variant":"Végétarien","change":"Un chou-fleur rôti à la marinade tandoori."}]$r$::jsonb, 'claude')
