insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('escalope de dinde', 'Escalope de dinde', array['dinde a la creme', 'escalope dinde creme']::text[], 'dish', $r$[{"title":"Escalopes de dinde à la crème","intro":"Des escalopes de dinde dorées, nappées d'une sauce crème aux champignons.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"turkey escalope cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"escalope de dinde","plural":"escalopes de dinde","qty":4,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":15,"unit":"g","have":false}],"steps":[{"text":"Fais dorer les escalopes 4 min de chaque côté dans le beurre et retire-les.","timer":{"label":"Poêle","min":8}},{"text":"Fais revenir l'échalote et les champignons 5 min.","timer":{"label":"Poêle","min":5}},{"text":"Ajoute la crème et laisse 2 min.","timer":null},{"text":"Remets les escalopes dans la sauce 2 min.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Escalopes de dinde au citron","intro":"Des escalopes légères, citron et câpres.","minutes":20,"calories":300,"difficulty":"Facile","imageSearch":"turkey piccata lemon capers","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"escalope de dinde","plural":"escalopes de dinde","qty":4,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"câpres","plural":"câpres","qty":1,"unit":"c. à s.","have":false},{"name":"farine","plural":"farines","qty":2,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false}],"steps":[{"text":"Farine légèrement les escalopes.","timer":null},{"text":"Fais-les dorer 3 min de chaque côté dans le beurre.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute le jus du citron, les câpres et 5 cl d'eau.","timer":null},{"text":"Laisse réduire 1 min.","timer":null}],"variant":"Citron","change":"Avec une sauce légère au citron et aux câpres."},{"title":"Escalopes de dinde au curry","intro":"Des escalopes de dinde en sauce curry douce.","minutes":25,"calories":380,"difficulty":"Facile","imageSearch":"turkey curry coconut","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"escalope de dinde","plural":"escalopes de dinde","qty":4,"unit":"","have":false},{"name":"lait de coco","plural":"lait de coco","qty":20,"unit":"cl","have":false},{"name":"curry","plural":"curry","qty":2,"unit":"c. à c.","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe la dinde en lanières et fais-la dorer avec l'oignon.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute le curry et le lait de coco.","timer":null},{"text":"Laisse mijoter 8 min.","timer":{"label":"Cuisson","min":8}}],"kids":true,"variant":"Au curry","change":"Avec une sauce curry coco."}]$r$::jsonb, 'claude')
