insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poulet au miel', 'Poulet au miel', array['poulet miel', 'poulet miel soja', 'poulet au miel et a la sauce soja']::text[], 'dish', $r$[{"title":"Poulet au miel et à la sauce soja","intro":"Des morceaux de poulet laqués au miel, à la sauce soja et à l'ail, avec du riz.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"honey soy chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"miel","plural":"miels","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":4,"unit":"c. à s.","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"graines de sésame","plural":"graines de sésame","qty":1,"unit":"c. à s.","have":false},{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le riz.","timer":{"label":"Cuisson","min":12}},{"text":"Coupe le poulet en morceaux et fais-le dorer 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute le miel, la sauce soja et l'ail.","timer":null},{"text":"Laisse réduire 3 min jusqu'à ce que le poulet soit laqué.","timer":{"label":"Cuisson","min":3}},{"text":"Parsème de sésame.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Cuisses de poulet au miel au four","intro":"Des cuisses de poulet dorées au miel et à la moutarde.","minutes":55,"calories":480,"difficulty":"Facile","imageSearch":"honey mustard chicken thighs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cuisse de poulet","plural":"cuisses de poulet","qty":4,"unit":"","have":false},{"name":"miel","plural":"miels","qty":3,"unit":"c. à s.","have":false},{"name":"moutarde","plural":"moutarde","qty":2,"unit":"c. à s.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":600,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Mélange le miel et la moutarde et badigeonne-en les cuisses.","timer":null},{"text":"Mets-les dans un plat avec les pommes de terre en quartiers et l'huile.","timer":null},{"text":"Enfourne 45 min en arrosant.","timer":{"label":"Four","min":45}}],"kids":true,"variant":"Au four","change":"Des cuisses rôties au four avec miel et moutarde."},{"title":"Poulet au miel et au citron","intro":"Un poulet frais et doux au miel et citron.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"honey lemon chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"miel","plural":"miels","qty":3,"unit":"c. à s.","have":false},{"name":"citron","plural":"citrons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le poulet en morceaux et fais-le dorer.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute le miel, le zeste et le jus du citron, l'ail et le thym.","timer":null},{"text":"Laisse réduire 3 min.","timer":{"label":"Cuisson","min":3}},{"text":"Sers avec du riz ou des légumes.","timer":null}],"variant":"Citron","change":"Avec une sauce miel-citron."}]$r$::jsonb, 'claude')
