insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('tarte aux fraise', 'Tarte aux fraises', array['tarte fraise', 'tarte aux fraise creme patissiere']::text[], 'dish', $r$[{"title":"Tarte aux fraises","intro":"Une pâte sablée, une crème pâtissière vanillée et des fraises fraîches.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"strawberry tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"Pâtisserie française","serves":4,"items":[{"name":"pâte sablée","plural":"pâtes sablées","qty":1,"unit":"","have":false},{"name":"fraise","plural":"fraises","qty":500,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":40,"unit":"g","have":false},{"name":"sucre vanillé","plural":"sucres vanillés","qty":1,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C. Garnis un moule de pâte, pique-la et fais-la cuire à blanc 20 min.","timer":{"label":"Four","min":20}},{"text":"Chauffe le lait. Fouette les œufs, le sucre, le sucre vanillé et la fécule.","timer":null},{"text":"Verse le lait chaud dessus, remets sur le feu et fouette jusqu'à ce que la crème épaississe.","timer":{"label":"Cuisson","min":3}},{"text":"Laisse refroidir la crème, puis étale-la sur le fond de tarte.","timer":null},{"text":"Dispose les fraises coupées en deux et garde au frais.","timer":null}],"dessert":true,"variant":"La classique","change":""},{"title":"Tarte aux fraises express","intro":"Une tarte aux fraises sans cuisson de crème, prête en 40 minutes.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"easy strawberry mascarpone tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte sablée","plural":"pâtes sablées","qty":1,"unit":"","have":false},{"name":"fraise","plural":"fraises","qty":500,"unit":"g","have":false},{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":15,"unit":"cl","have":false},{"name":"sucre glace","plural":"sucre glace","qty":50,"unit":"g","have":false}],"steps":[{"text":"Fais cuire la pâte à blanc 20 min à 180 °C et laisse refroidir.","timer":{"label":"Four","min":20}},{"text":"Fouette le mascarpone, la crème froide et le sucre glace jusqu'à ce que ce soit ferme.","timer":null},{"text":"Étale sur le fond de tarte.","timer":null},{"text":"Dispose les fraises.","timer":null}],"dessert":true,"variant":"Express","change":"Avec du mascarpone à la place de la crème pâtissière."},{"title":"Tarte aux fraises sans cuisson","intro":"Une tarte aux fraises fraîche, sans four.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"no bake strawberry tart","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"biscuits secs","plural":"biscuits secs","qty":200,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":80,"unit":"g","have":false},{"name":"fraise","plural":"fraises","qty":500,"unit":"g","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":250,"unit":"g","have":false},{"name":"crème liquide entière","plural":"crème liquide entière","qty":15,"unit":"cl","have":false},{"name":"sucre glace","plural":"sucre glace","qty":50,"unit":"g","have":false}],"steps":[{"text":"Écrase les biscuits, mélange-les au beurre fondu et tasse au fond d'un moule.","timer":null},{"text":"Laisse durcir 30 min au frais.","timer":null},{"text":"Fouette la crème en chantilly et mélange-la au fromage blanc et au sucre glace.","timer":null},{"text":"Étale sur la base et dispose les fraises.","timer":null}],"dessert":true,"variant":"Sans four","change":"Une base de biscuits écrasés."}]$r$::jsonb, 'claude')
