insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('far breton', 'Far breton', array['far aux pruneau', 'far', 'far breton aux pruneau']::text[], 'dish', $r$[{"title":"Far breton aux pruneaux","intro":"Le flan épais breton aux pruneaux, doré et moelleux.","minutes":70,"calories":300,"difficulty":"Facile","imageSearch":"far breton prunes","veg":true,"oven":true,"cold":false,"missing":"","origin":"Spécialité bretonne","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"lait","plural":"laits","qty":75,"unit":"cl","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"pruneaux","plural":"pruneaux","qty":200,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Beurre un plat.","timer":null},{"text":"Mélange la farine, le sucre et une pincée de sel, puis ajoute les œufs un à un.","timer":null},{"text":"Verse le lait petit à petit en fouettant.","timer":null},{"text":"Répartis les pruneaux dans le plat et verse la pâte.","timer":null},{"text":"Parsème de beurre en noisettes et enfourne 45 min.","timer":{"label":"Four","min":45}}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Far breton nature","intro":"Le far nature à la vanille, pour ceux qui n'aiment pas les pruneaux.","minutes":65,"calories":280,"difficulty":"Facile","imageSearch":"plain far breton","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"lait","plural":"laits","qty":75,"unit":"cl","have":false},{"name":"beurre","p