insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('churro', 'Churros', array['churro maison', 'chichi']::text[], 'dish', $r$[{"title":"Churros","intro":"Les beignets espagnols striés, croustillants et roulés dans le sucre à la cannelle.","minutes":30,"calories":300,"difficulty":"Moyen","imageSearch":"churros cinnamon sugar","veg":true,"oven":false,"cold":false,"missing":"","origin":"Recette espagnole","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"cannelle","plural":"cannelle","qty":1,"unit":"c. à c.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Porte à ébullition 25 cl d'eau avec le beurre et une pincée de sel.","timer":null},{"text":"Verse la farine d'un coup et remue jusqu'à ce que la pâte forme une boule.","timer":null},{"text":"Mets la pâte dans une poche à douille cannelée.","timer":null},{"text":"Fais tomber des boudins de 10 cm dans l'huile chaude et fais-les frire 3 min.","timer":{"label":"Friture","min":3}},{"text":"Égoutte et roule-les dans le sucre mélangé à la cannelle.","timer":null}],"kids":true,"dessert":true,"variant":"La classique","change":""},{"title":"Churros et sauce chocolat","intro":"Les churros avec leur chocolat chaud épais, comme en Espagne.","minutes":35,"calories":420,"difficulty":"Moyen","imageSearch":"churros chocolate sauce","veg":true,"oven":false,"cold":false,"missing":"","origin":"Recette espagnole","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":60,"unit":"g","have":false},{"name":"huile de friture","plural":"huile de