},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":50,"unit":"g","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":50,"unit":"g","have":false},{"name":"chocolat noir","plural":"chocolat noir","qty":150,"unit":"g","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Prépare la pâte et laisse lever 1 h 30.","timer":{"label":"Levée","min":90}},{"text":"Découpe des anneaux et laisse lever 30 min.","timer":{"label":"Levée","min":30}},{"text":"Fais frire 1 min de chaque côté.","timer":{"label":"Friture","min":2}},{"text":"Trempe le dessus dans le chocolat fondu.","timer":null}],"kids":true,"dessert":true,"variant":"Chocolat","change":"Avec un glaçage au chocolat."},{"title":"Donuts au four","intro":"Des donuts plus légers, sans friture.","minutes":30,"calories":230,"difficulty":"Facile","imageSearch":"baked donuts","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"lait","plural":"laits","qty":12,"unit":"cl","have":false},{"name":"beurre fondu","plural":"beurre fondu","qty":50,"unit":"g","have":false},{"name":"levure chimique","plural":"levure chimique","qty":2,"unit":"c. à c.","have":false},{"name":"sucre glace","plural":"sucre glace","qty":100,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Mélange tous les ingrédients sauf le sucre glace.","timer":null},{"text":"Remplis un moule à donuts beurré et enfourne 12 min.","timer":{"label":"Four","min":12}},{"text":"Trempe le dessus dans le sucre glace délayé avec un peu d'eau.","timer":null}],"kids":true,"dessert":true,"variant":"Au four","