insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('empanada', 'Empanadas', array['chausson argentin', 'empanada au boeuf']::text[], 'dish', $r$[{"title":"Empanadas au bœuf","intro":"Des chaussons argentins dorés, farcis au bœuf, aux oignons et au paprika.","minutes":60,"calories":380,"difficulty":"Moyen","imageSearch":"beef empanadas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Recette argentine","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":2,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"c. à c.","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false}],"steps":[{"text":"Fais revenir les oignons et le poivron en dés, puis le bœuf et les épices 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Fais durcir un œuf 10 min, hache-le et ajoute-le à la farce.","timer":{"label":"Cuisson","min":10}},{"text":"Préchauffe le four à 200 °C. Découpe des disques de 12 cm dans les pâtes.","timer":null},{"text":"Garnis la moitié de chaque disque, replie et soude les bords à la fourchette.","timer":null},{"text":"Dore au second œuf battu et enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"La classique","change":""},{"title":"Empanadas au poulet","intro":"Des empanadas plus douces au poulet.","minutes":60,"calories":350,"difficulty":"Moyen","imageSearch":"chicken empanadas","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":2,"unit":"","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"maïs","plural":"maïs","qty":140,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon, le poivron, puis le poulet en petits dés avec le paprika.","timer":{"label":"Poêle","min":8}},{"text":"Ajoute le maïs.","timer":null},{"text":"Garnis des disques de pâte, replie et soude.","timer":null},{"text":"Dore à l'œuf et enfourne 20 min à 200 °C.","timer":{"label":"Four","min":20}}],"variant":"Au poulet","change":"Farcies de poulet, maïs et poivron."},{"title":"Empanadas au fromage","intro":"Des empanadas végétariennes fondantes.","minutes":50,"calories":340,"difficulty":"Moyen","imageSearch":"cheese spinach empanadas","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":2,"unit":"","have":false},{"name":"pousses d'épinard","plural":"pousses d'épinard","qty":200,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"feta","plural":"fetas","qty":100,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais fondre l'oignon et les épinards.","timer":{"label":"Poêle","min":5}},{"text":"Mélange avec la mozzarella en dés et la feta émiettée.","timer":null},{"text":"Garnis des disques de pâte, replie et soude.","timer":null},{"text":"Dore à l'œuf et enfourne 20 min à 200 °C.","timer":{"label":"Four","min":20}}],"variant":"Végétariennes","change":"Farcies au fromage et aux épinards."}]$r$::jsonb, 'claude')
