insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('quesadilla', 'Quesadillas', array['quesadilla poulet', 'quesadilla fromage']::text[], 'dish', $r$[{"title":"Quesadillas au poulet","intro":"Des tortillas dorées à la poêle, garnies de poulet, poivrons et fromage fondu.","minutes":25,"calories":480,"difficulty":"Facile","imageSearch":"chicken quesadillas","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette mexicaine","serves":4,"items":[{"name":"tortilla de blé","plural":"tortillas de blé","qty":8,"unit":"","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":150,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir le poulet en lamelles avec le poivron et le paprika 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Garnis 4 tortillas de fromage, de poulet et encore de fromage.","timer":null},{"text":"Couvre d'une deuxième tortilla.","timer":null},{"text":"Fais dorer 2 min de chaque côté dans une poêle sèche.","timer":{"label":"Poêle","min":4}},{"text":"Coupe en parts et sers avec la crème.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Quesadillas au fromage et haricots","intro":"Des quesadillas végétariennes et fondantes.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"bean cheese quesadillas","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tortilla de blé","plural":"tortillas de blé","qty":8,"unit":"","have":false},{"name":"haricots rouges","plural":"haricots rouges","qty":250,"unit":"g","have":false},{"name":"maïs","plural":"maïs","qty":140,"unit":"g","have":false},{"name":"ch