insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('enchilada', 'Enchiladas', array['enchilada poulet', 'enchilada au poulet']::text[], 'dish', $r$[{"title":"Enchiladas au poulet","intro":"Des tortillas roulées autour du poulet, nappées de sauce tomate épicée et gratinées.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"chicken enchiladas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Recette mexicaine","serves":4,"items":[{"name":"tortilla de blé","plural":"tortillas de blé","qty":8,"unit":"","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":3,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":600,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":150,"unit":"g","have":false}],"steps":[{"text":"Fais cuire le poulet 15 min à l'eau frémissante et effiloche-le.","timer":{"label":"Cuisson","min":15}},{"text":"Fais revenir l'oignon, ajoute les tomates, le cumin et le piment, et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Préchauffe le four à 200 °C. Mélange le poulet avec un tiers de la sauce.","timer":null},{"text":"Roule le poulet dans les tortillas et range-les dans un plat.","timer":null},{"text":"Nappe du reste de sauce, couvre de cheddar et enfourne 20 min.","timer":{"label":"Four","min":20}}],"variant":"La classique","change":""},{"title":"Enchiladas au bœuf","intro":"Des enchiladas généreuses au bœuf.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"beef enchiladas","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tortilla de blé","plural":"tortillas de blé","qty":8,"unit":"","have":false},{"name":"bœuf haché","plural":"bœuf haché","qty":400,"unit":"g","have":false},{"name":"haricots rouges","plural":"haricots rouges","qty":250,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":600,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":150,"unit":"g","have":false}],"steps":[{"text":"Fais revenir le bœuf avec le cumin, puis ajoute les haricots.","timer":{"label":"Poêle","min":8}},{"text":"Fais chauffer les tomates 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Roule la farce dans les tortillas et range-les dans un plat.","timer":null},{"text":"Nappe de sauce, couvre de cheddar et enfourne 20 min à 200 °C.","timer":{"label":"Four","min":20}}],"variant":"Au bœuf","change":"Farcies au bœuf haché et aux haricots."},{"title":"Enchiladas végétariennes","intro":"Des enchiladas végétariennes douces et épicées.","minutes":55,"calories":500,"difficulty":"Facile","imageSearch":"vegetarian enchiladas sweet potato","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tortilla de blé","plural":"tortillas de blé","qty":8,"unit":"","have":false},{"name":"patate douce","plural":"patates douces","qty":2,"unit":"","have":false},{"name":"haricots noirs","plural":"haricots noirs","qty":250,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":600,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":120,"unit":"g","have":false}],"steps":[{"text":"Fais cuire la patate douce en dés 12 min à l'eau.","timer":{"label":"Cuisson","min":12}},{"text":"Mélange-la avec les haricots et le cumin.","timer":null},{"text":"Roule dans les tortillas et range-les dans un plat.","timer":null},{"text":"Nappe de tomates, couvre de cheddar et enfourne 20 min à 200 °C.","timer":{"label":"Four","min":20}}],"variant":"Végétariennes","change":"Farcies de patate douce et de haricots noirs."}]$r$::jsonb, 'claude')
