tes concassées","qty":200,"unit":"g","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":150,"unit":"g","have":false}],"steps":[{"text":"Fais revenir le bœuf avec le cumin, ajoute les haricots et les tomates, et laisse 10 min.","timer":{"label":"Cuisson","min":10}},{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Étale les chips, couvre de chili et de cheddar.","timer":null},{"text":"Enfourne 8 min.","timer":{"label":"Four","min":8}}],"variant":"Au chili","change":"Avec du bœuf haché épicé."},{"title":"Nachos au poulet","intro":"Des nachos gratinés au poulet et au maïs.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"chicken nachos","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chips de maïs","plural":"chips de maïs","qty":200,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"maïs","plural":"maïs","qty":140,"unit":"g","have":false},{"name":"cheddar râpé","plural":"cheddar râpé","qty":150,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le poulet en lamelles avec le paprika.","timer":{"label":"Poêle","min":8}},{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Étale les chips, ajoute le poulet, le maïs et le cheddar.","timer":null},{"text":"Enfourne 8 min et sers avec la crème.","timer":{"label":"Four","min":8}}],"variant":"Au poulet","change":"Avec du poulet effiloché."}]$r$::jsonb, 'claude')
