insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('bagel', 'Bagels', array['bagel saumon', 'bagel maison']::text[], 'dish', $r$[{"title":"Bagel saumon et fromage frais","intro":"Le bagel new-yorkais au fromage frais, saumon fumé, oignon rouge et aneth.","minutes":10,"calories":420,"difficulty":"Facile","imageSearch":"salmon cream cheese bagel","veg":false,"oven":false,"cold":true,"missing":"","origin":"Recette new-yorkaise","serves":4,"items":[{"name":"bagel","plural":"bagels","qty":4,"unit":"","have":false},{"name":"fromage frais","plural":"fromage frais","qty":150,"unit":"g","have":false},{"name":"saumon fumé","plural":"saumon fumé","qty":4,"unit":"tranches","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":0.5,"unit":"","have":false},{"name":"aneth","plural":"aneth","qty":null,"unit":"","have":false},{"name":"citron","plural":"citrons","qty":0.5,"unit":"","have":false}],"steps":[{"text":"Coupe les bagels en deux et fais-les griller.","timer":null},{"text":"Tartine de fromage frais.","timer":null},{"text":"Ajoute le saumon, l'oignon émincé et l'aneth.","timer":null},{"text":"Arrose d'un peu de jus de citron et referme.","timer":null}],"variant":"La classique","change":""},{"title":"Bagel poulet et crudités","intro":"Un bagel complet au poulet pour le déjeuner.","minutes":15,"calories":450,"difficulty":"Facile","imageSearch":"chicken bagel sandwich","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"bagel","plural":"bagels","qty":4,"unit":"","have":false},{"name":"blanc de poulet cuit","plural":"blancs de poulet cuits","qty":2,"unit":"","have":false},{"name":"salade verte","plural":"salade verte","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"yaourt grec","plural":"yaourts grecs","qty":1,"unit":"","have":false},{"name":"moutarde","plural":"moutarde","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Mélange le yaourt et la moutarde.","timer":null},{"text":"Coupe les bagels en deux et tartine-les de sauce.","timer":null},{"text":"Ajoute la salade, la tomate en rondelles et le poulet en tranches.","timer":null},{"text":"Referme.","timer":null}],"variant":"Au poulet","change":"Avec du poulet, de la salade et une sauce au yaourt."},{"title":"Bagel végétarien","intro":"Un bagel végétarien à l'avocat et à l'œuf.","minutes":15,"calories":430,"difficulty":"Facile","imageSearch":"avocado egg bagel","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"bagel","plural":"bagels","qty":4,"unit":"","have":false},{"name":"avocat","plural":"avocats","qty":2,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"fromage frais","plural":"fromage frais","qty":100,"unit":"g","have":false},{"name":"roquette","plural":"roquette","qty":40,"unit":"g","have":false}],"steps":[{"text":"Fais cuire les œufs 9 min et coupe-les en rondelles.","timer":{"label":"Cuisson","min":9}},{"text":"Tartine les bagels grillés de fromage frais.","timer":null},{"text":"Ajoute l'avocat en lamelles, l'œuf et la roquette.","timer":null},{"text":"Sale, poivre et referme.","timer":null}],"variant":"Végétarien","change":"Avec avocat, œuf et fromage frais."}]$r$::jsonb, 'claude')
