insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('poutine', 'Poutine', array['poutine quebecoise', 'frite sauce fromage']::text[], 'dish', $r$[{"title":"Poutine","intro":"Le plat québécois : frites, fromage en grains et sauce brune bien chaude.","minutes":50,"calories":750,"difficulty":"Facile","imageSearch":"poutine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette québécoise","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false},{"name":"cheddar","plural":"cheddar","qty":200,"unit":"g","have":false},{"name":"bouillon de bœuf","plural":"bouillons de bœuf","qty":2,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":2,"unit":"c. à s.","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false}],"steps":[{"text":"Coupe les pommes de terre en frites et fais-les frire deux fois : 6 min à 160 °C, puis 3 min à 180 °C.","timer":{"label":"Friture","min":9}},{"text":"Chauffe 40 cl d'eau avec les bouillons et le beurre.","timer":null},{"text":"Ajoute la fécule délayée et laisse épaissir.","timer":{"label":"Cuisson","min":3}},{"text":"Coupe le cheddar en petits morceaux.","timer":null},{"text":"Mets les frites dans les assiettes, ajoute le fromage et nappe de sauce bouillante.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Poutine au four","intro":"Une poutine un peu plus légère, aux frites cuites au four.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"oven fries poutine","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"cheddar","plural":"cheddar","qty":200,"unit":"g","have":false},{"name":"bouillon de bœuf","plural":"bouillons de bœuf","qty":2,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Préchauffe le four à 220 °C. Coupe les pommes de terre en frites et mélange-les avec l'huile.","timer":null},{"text":"Enfourne 35 min en les retournant.","timer":{"label":"Four","min":35}},{"text":"Prépare la sauce avec le bouillon et la fécule.","timer":{"label":"Cuisson","min":3}},{"text":"Garnis les frites de fromage et nappe de sauce.","timer":null}],"kids":true,"variant":"Frites au four","change":"Avec des frites au four."},{"title":"Poutine au poulet","intro":"La poutine en plat complet, au poulet.","minutes":55,"calories":800,"difficulty":"Facile","imageSearch":"chicken poutine","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"cheddar","plural":"cheddar","qty":200,"unit":"g","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":2,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais cuire le poulet 15 min dans le bouillon avec 40 cl d'eau, puis effiloche-le.","timer":{"label":"Cuisson","min":15}},{"text":"Épaissis le bouillon avec la fécule.","timer":{"label":"Cuisson","min":3}},{"text":"Fais frire les frites en deux fois.","timer":{"label":"Friture","min":9}},{"text":"Garnis les frites de poulet et de fromage, et nappe de sauce.","timer":null}],"variant":"Au poulet","change":"Avec du poulet effiloché."}]$r$::jsonb, 'claude')
