insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('goulash', 'Goulash', array['goulasch', 'goulache', 'boeuf au paprika']::text[], 'dish', $r$[{"title":"Goulash","intro":"Le ragoût hongrois de bœuf au paprika, aux oignons et aux poivrons.","minutes":150,"calories":520,"difficulty":"Facile","imageSearch":"hungarian goulash","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette hongroise","serves":4,"items":[{"name":"bœuf à braiser","plural":"bœuf à braiser","qty":1000,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":3,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"paprika","plural":"paprika","qty":3,"unit":"c. à s.","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":4,"unit":"","have":false}],"steps":[{"text":"Coupe le bœuf en cubes et fais-le dorer dans une cocotte.","timer":{"label":"Cuisson","min":10}},{"text":"Ajoute les oignons émincés et laisse fondre 5 min.","timer":null},{"text":"Ajoute le paprika, le cumin, les tomates et 50 cl d'eau.","timer":null},{"text":"Couvre et laisse mijoter 1 h 30.","timer":{"label":"Cuisson","min":90}},{"text":"Ajoute les poivrons et les pommes de terre en dés, et laisse 30 min.","timer":{"label":"Cuisson","min":30}}],"variant":"La classique","change":""},{"title":"Goulash de porc","intro":"Un goulash plus tendre, à l'échine de porc.","minutes":90,"calories":540,"difficulty":"Facile","imageSearch":"pork goulash","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"échine de porc","plural":"échines de porc","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":3,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"",