:null},{"text":"Fais cuire les haricots verts 8 min à l'eau.","timer":{"label":"Cuisson","min":8}},{"text":"Fais dorer les steaks 3 min de chaque côté.","timer":{"label":"Poêle","min":6}}],"kids":true,"variant":"Maison","change":"Façonnés à la main avec des herbes et de l'oignon."},{"title":"Steak haché à la sauce au poivre","intro":"Le steak haché du bistrot, sauce au poivre.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"patty pepper sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"steak haché","plural":"steaks hachés","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"poivre concassé","plural":"poivre concassé","qty":1,"unit":"c. à c.","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false}],"steps":[{"text":"Fais cuire les pommes de terre en quartiers 20 min à la vapeur.","timer":{"label":"Cuisson","min":20}},{"text":"Fais cuire les steaks et retire-les.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir l'échalote, ajoute la crème et le poivre, et laisse réduire 2 min.","timer":null},{"text":"Nappe les steaks de sauce.","timer":null}],"variant":"Sauce poivre","change":"Avec une sauce crème au poivre."}]$r$::jsonb, 'claude')
