insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('veloute de tomate', 'Velouté de tomates', array['soupe de tomate', 'soupe a la tomate', 'veloute tomate', 'creme de tomate']::text[], 'dish', $r$[{"title":"Velouté de tomates","intro":"Un velouté de tomates doux et parfumé au basilic, avec un trait de crème.","minutes":35,"calories":160,"difficulty":"Facile","imageSearch":"tomato soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":8,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":1,"unit":"gousse","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":2,"unit":"c. à s.","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":1,"unit":"c. à c.","have":false}],"steps":[{"text":"Fais revenir l'oignon et l'ail.","timer":null},{"text":"Ajoute les tomates en quartiers, le sucre, le bouillon et 40 cl d'eau.","timer":null},{"text":"Laisse cuire 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Mixe avec la crème et le basilic.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Soupe de tomates rôties","intro":"Une soupe de tomates plus intense, rôties au four.","minutes":50,"calories":170,"difficulty":"Facile","imageSearch":"roasted tomato soup","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":10,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"thym","plural":"thym","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Mets les tomates coupées en deux, l'oignon et l'ail dans un plat avec l'huile et le thym.","timer":null},{"text":"Enfourne 35 min.","timer":{"label":"Four","min":35}},{"text":"Mixe avec le bouillon et 30 cl d'eau chaude.","timer":null}],"variant":"Rôties","change":"Les tomates sont rôties au four avant d'être mixées."},{"title":"Soupe de tomates et croque au fromage","intro":"La soupe à la tomate et son sandwich au fromage fondu.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"tomato soup grilled cheese","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"bouillon de légumes","plural":"bouillon de légumes","qty":1,"unit":"","have":false},{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"cheddar","plural":"cheddar","qty":8,"unit":"tranches","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false}],"steps":[{"text":"Fais revenir l'oignon, ajoute les tomates, le bouillon et 30 cl d'eau, et laisse 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Mixe la soupe.","timer":null},{"text":"Garnis le pain de cheddar, beurre l'extérieur et fais dorer à la poêle 3 min de chaque côté.","timer":{"label":"Poêle","min":6}},{"text":"Coupe en bâtonnets et sers avec la soupe.","timer":null}],"kids":true,"variant":"Avec croques","change":"Servie avec des petits croques au fromage à tremper."}]$r$::jsonb, 'claude')
