insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('pate a la sauce tomate', 'Pâtes à la sauce tomate', array['sauce tomate', 'pate tomate', 'spaghetti sauce tomate', 'sauce tomate maison', 'pate sauce tomate']::text[], 'dish', $r$[{"title":"Pâtes à la sauce tomate maison","intro":"Des pâtes avec une vraie sauce tomate maison, à l'ail et au basilic.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"pasta tomato sauce","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false},{"name":"parmesan","plural":"parmesans","qty":40,"unit":"g","have":false}],"steps":[{"text":"Fais revenir l'oignon et l'ail dans l'huile.","timer":null},{"text":"Ajoute les tomates, sale, poivre et laisse mijoter 20 min.","timer":{"label":"Cuisson","min":20}},{"text":"Fais cuire les pâtes.","timer":{"label":"Cuisson","min":10}},{"text":"Mélange avec la sauce, le basilic et le parmesan.","timer":null}],"kids":true,"variant":"La classique","change":""},{"title":"Pâtes sauce tomate et légumes cachés","intro":"Une sauce tomate pleine de légumes, que les enfants ne voient pas.","minutes":35,"calories":430,"difficulty":"Facile","imageSearch":"hidden veggie pasta sauce","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir l'oignon, la carotte, la courgette et le poivron en dés 5 min.","timer":null},{"text":"Ajoute les tomates et laisse mijoter 25 min.","timer":{"label":"Cuisson","min":25}},{"text":"Mixe la sauce.","timer":null},{"text":"Fais cuire les pâtes et mélange avec la sauce.","timer":{"label":"Cuisson","min":10}}],"kids":true,"variant":"Légumes cachés","change":"Des légumes mixés dans la sauce."},{"title":"Pâtes sauce tomate et thon","intro":"Une sauce tomate enrichie au thon.","minutes":25,"calories":500,"difficulty":"Facile","imageSearch":"tuna tomato pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâtes","plural":"pâtes","qty":400,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"câpres","plural":"câpres","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais revenir l'ail, ajoute les tomates et laisse 15 min.","timer":{"label":"Cuisson","min":15}},{"text":"Ajoute le thon et les câpres.","timer":null},{"text":"Fais cuire les pâtes.","timer":{"label":"Cuisson","min":10}},{"text":"Mélange avec la sauce.","timer":null}],"kids":true,"variant":"Au thon","change":"Avec du thon et des câpres."}]$r$::jsonb, 'claude')
