insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('gratin de poisson', 'Gratin de poisson', array['gratin de poisson blanc', 'poisson gratine', 'gratin de cabillaud']::text[], 'dish', $r$[{"title":"Gratin de poisson","intro":"Du poisson blanc en béchamel, gratiné à l'emmental, avec des pommes de terre.","minutes":50,"calories":450,"difficulty":"Facile","imageSearch":"fish gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filets de poisson blanc","plural":"filets de poisson blanc","qty":600,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":600,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":100,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais cuire les pommes de terre en rondelles 10 min à l'eau.","timer":{"label":"Cuisson","min":10}},{"text":"Prépare une béchamel avec le beurre, la farine et le lait.","timer":null},{"text":"Range les pommes de terre et le poisson en morceaux dans un plat.","timer":null},{"text":"Nappe de béchamel et couvre d'emmental.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true,"variant":"La classique","change":""},{"title":"Gratin de poisson aux épinards","intro":"Un gratin de poisson vert, aux épinards.","minutes":40,"calories":400,"difficulty":"Facile","imageSearch":"fish spinach gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filets de poisson blanc","plural":"filets de poisson blanc","qty":600,"unit":"g","have":false},{"name":"épinards surgelés","plural":"épinards surgelés","qty":500,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"parmesan","plural":"parmesans","qty":50,"unit":"g","have":false},{"name":"muscade","plural":"muscade","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Fais décongeler les épinards et presse-les.","timer":null},{"text":"Mélange-les avec la crème et la muscade.","timer":null},{"text":"Mets le poisson dans un plat et couvre d'épinards.","timer":null},{"text":"Parsème de parmesan et enfourne 25 min.","timer":{"label":"Four","min":25}}],"variant":"Épinards","change":"Avec des épinards à la crème."},{"title":"Gratin de poisson à la tomate","intro":"Un gratin de poisson à l'italienne.","minutes":40,"calories":380,"difficulty":"Facile","imageSearch":"fish tomato mozzarella bake","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filets de poisson blanc","plural":"filets de poisson blanc","qty":600,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"olives noires","plural":"olives noires","qty":50,"unit":"g","have":false},{"name":"basilic","plural":"basilic","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Étale les tomates dans un plat et pose le poisson dessus.","timer":null},{"text":"Ajoute les olives et la mozzarella en tranches.","timer":null},{"text":"Enfourne 25 min et parsème de basilic.","timer":{"label":"Four","min":25}}],"variant":"Tomate","change":"Avec une sauce tomate et de la mozzarella."}]$r$::jsonb, 'claude')
